#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/linker/sections.h>

struct foo {
	int val;
};

static int get_sum(const struct foo *f)
{
	return f->val;
}

/* ROM section */
#define ROM_ADD(idx, _val) \
	const STRUCT_SECTION_ITERABLE(rodata.rom, struct foo) rom_data_##idx = { .val = _val }

ROM_ADD(0, 1);
ROM_ADD(1, 2);
ROM_ADD(2, 3);
ROM_ADD(3, 5);
ROM_ADD(4, 8);

#define ROM_EXPECT (1 + 2 + 3 + 5 + 8)

/* RAM section */
#define RAM_ADD(idx, _val) \
	STRUCT_SECTION_ITERABLE(data.ram, struct foo) ram_data_##idx = { .val = _val }

RAM_ADD(0, 13);
RAM_ADD(1, 21);
RAM_ADD(2, 34);
RAM_ADD(3, 55);
RAM_ADD(4, 89);

#define RAM_EXPECT (13 + 21 + 34 + 55 + 89)

/* BSS section */
#define BSS_ADD(idx) \
	STRUCT_SECTION_ITERABLE(bss.bss, struct foo) bss_data_##idx

BSS_ADD(0);
BSS_ADD(1);
BSS_ADD(2);

static void iterable_sections_test_rom(void)
{
	int out = 0;

	STRUCT_SECTION_FOREACH(rodata.rom, struct foo, f) {
		out += get_sum(f);
	}

	zassert_equal(out, ROM_EXPECT, "ROM iterable section sum mismatch");
}

static void iterable_sections_test_ram(void)
{
	int out = 0;

	STRUCT_SECTION_FOREACH(data.ram, struct foo, f) {
		out += get_sum(f);
	}

	zassert_equal(out, RAM_EXPECT, "RAM iterable section sum mismatch");
}

static void iterable_sections_test_bss(void)
{
	int count = 0;

	STRUCT_SECTION_FOREACH(bss.bss, struct foo, f) {
		count++;
		f->val = count;
	}

	zassert_equal(count, 3, "BSS iterable section count mismatch");

	/* Check that we can write to the elements and read back the values */
	count = 0;
	STRUCT_SECTION_FOREACH(bss.bss, struct foo, f) {
		count++;
		zassert_equal(f->val, count, "BSS data invalid");
	}
}

ZTEST(iterable_sections, test_rom)
{
	iterable_sections_test_rom();
}

ZTEST(iterable_sections, test_ram)
{
	iterable_sections_test_ram();
}

ZTEST(iterable_sections, test_bss)
{
	iterable_sections_test_bss();
}

ZTEST_SUITE(iterable_sections, NULL, NULL, NULL, NULL, NULL);
